-- Add skills_rubric column to jobs table for the JD Intelligence Agent.
-- Stores the full scoring rubric (mustHaves, niceToHaves, scoringCriteria,
-- idealCandidateProfile, redFlagIndicators) generated by Claude.
-- Downstream agents (Screening, Fit Score) read this for candidate evaluation.

ALTER TABLE jobs ADD COLUMN IF NOT EXISTS skills_rubric jsonb;

COMMENT ON COLUMN jobs.skills_rubric IS 'AI-generated scoring rubric from the JD Intelligence Agent';
